// skins (a colour table per buddy), hats / eyewear / neckwear / back items (one overlay per buddy)
// and backdrops (shared scenes). Every item is cosmetic: nothing here touches a goal or a lock.

/// The eight colourways every buddy can buy. A skin recolours the buddy's main body ramp only
/// (`Buddy.skinColours`), so the face, belly and props keep their own colours.
public enum BuddySkin: String, CaseIterable, Sendable, Identifiable {
    case midnight, sunset, mint, bubblegum, gold, ghost, lava, galaxy

    public var id: String { rawValue }
}

/// Where an item goes. A buddy wears at most one item per slot (plus a skin and a backdrop).
public enum BuddyStyleSlot: String, CaseIterable, Sendable {
    case hat, eyewear, neck, back, backdrop
}

/// Every hat, pair of glasses, neckwear, back item and backdrop. Bought once, worn by any buddy.
public enum BuddyStyleItem: String, CaseIterable, Sendable, Identifiable {
    case hatCap, hatWizard, hatChef, hatCowboy, hatTophat, hatHalo, hatHeadband, hatSanta, hatPirate, hatFlowers, eyewearRoundGlasses, eyewearHeartShades, eyewearStarShades, eyewearGoggles, neckBowtie, neckScarf, neckBandana, neckGoldChain, neckCollarBell, neckTie, backAngelWings, backBatWings, backButterflyWings, backDragonWings, backLeafWings, backBackpack, backdropSunrise, backdropGym, backdropForest, backdropSpace, backdropBeach, backdropCity, backdropSnow, backdropCandy, backdropLibrary, backdropArcade

    public var id: String { rawValue }

    public var slot: BuddyStyleSlot {
        switch self {
        case .hatCap, .hatWizard, .hatChef, .hatCowboy, .hatTophat, .hatHalo, .hatHeadband, .hatSanta, .hatPirate, .hatFlowers: .hat
        case .eyewearRoundGlasses, .eyewearHeartShades, .eyewearStarShades, .eyewearGoggles: .eyewear
        case .neckBowtie, .neckScarf, .neckBandana, .neckGoldChain, .neckCollarBell, .neckTie: .neck
        case .backAngelWings, .backBatWings, .backButterflyWings, .backDragonWings, .backLeafWings, .backBackpack: .back
        case .backdropSunrise, .backdropGym, .backdropForest, .backdropSpace, .backdropBeach, .backdropCity, .backdropSnow, .backdropCandy, .backdropLibrary, .backdropArcade: .backdrop
        }
    }

    /// The scene drawn behind the buddy (nil unless this is a backdrop).
    public func backdropPixels() -> BuddyPixels? {
        switch self {
        case .backdropSunrise: BuddyStyleSpriteData.backdropSunrise
        case .backdropGym: BuddyStyleSpriteData.backdropGym
        case .backdropForest: BuddyStyleSpriteData.backdropForest
        case .backdropSpace: BuddyStyleSpriteData.backdropSpace
        case .backdropBeach: BuddyStyleSpriteData.backdropBeach
        case .backdropCity: BuddyStyleSpriteData.backdropCity
        case .backdropSnow: BuddyStyleSpriteData.backdropSnow
        case .backdropCandy: BuddyStyleSpriteData.backdropCandy
        case .backdropLibrary: BuddyStyleSpriteData.backdropLibrary
        case .backdropArcade: BuddyStyleSpriteData.backdropArcade
        default: nil
        }
    }
}

