        case (.howl, .backAngelWings, _): BuddyStyleSpriteData.howlBackAngelWings
        case (.howl, .backBatWings, _): BuddyStyleSpriteData.howlBackBatWings
        case (.howl, .backButterflyWings, _): BuddyStyleSpriteData.howlBackButterflyWings
